<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/app.php';
$search = trim((string) ($_GET['search'] ?? '')); $categoryId = filter_input(INPUT_GET, 'category', FILTER_VALIDATE_INT) ?: 0;
$categories = fetchCategories($pdo); $where = []; $params = [];
if ($search !== '') { $where[] = '(books.title LIKE :search_title OR books.author LIKE :search_author)'; $params['search_title'] = '%' . $search . '%'; $params['search_author'] = '%' . $search . '%'; }
if ($categoryId > 0) { $where[] = 'books.category_id = :category'; $params['category'] = $categoryId; }
$countSql = 'SELECT COUNT(*) FROM books'; if ($where) { $countSql .= ' WHERE ' . implode(' AND ', $where); }
$countStatement = $pdo->prepare($countSql); $countStatement->execute($params); $totalBooks = (int) $countStatement->fetchColumn();
$perPage = 12; $totalPages = max(1, (int) ceil($totalBooks / $perPage)); $currentPage = min(max(1, filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT) ?: 1), $totalPages); $offset = ($currentPage - 1) * $perPage;
$sql = 'SELECT books.id, books.title, books.author, books.description, books.image, books.price, categories.name AS category_name FROM books LEFT JOIN categories ON categories.id = books.category_id'; if ($where) { $sql .= ' WHERE ' . implode(' AND ', $where); } $sql .= ' ORDER BY books.id DESC LIMIT :limit OFFSET :offset';
$statement = $pdo->prepare($sql); foreach ($params as $key => $value) { $statement->bindValue(':' . $key, $value); } $statement->bindValue(':limit', $perPage, PDO::PARAM_INT); $statement->bindValue(':offset', $offset, PDO::PARAM_INT); $statement->execute(); $books = $statement->fetchAll();
$pageTitle = 'الكتب'; $activePage = 'books'; require __DIR__ . '/includes/header.php';
?>
<section class="page-intro"><div class="container"><p class="eyebrow">رفوف مكتبة بُعد</p><h1>كل الكتب</h1><p>ابحث عن العنوان الذي يثير فضولك.</p></div></section><section class="section"><div class="container"><form class="filter-bar" method="get"><input name="search" value="<?= e($search) ?>" placeholder="ابحث بعنوان الكتاب أو المؤلف" aria-label="بحث في الكتب"><select name="category" aria-label="فلترة حسب التصنيف"><option value="0">كل التصنيفات</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= $categoryId === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><button class="button button-primary" type="submit">بحث</button></form><?php if (!$books): ?><div class="empty-state">لم نعثر على كتب تطابق بحثك.</div><?php else: ?><div class="book-grid"><?php foreach ($books as $book): ?><article class="book-card"><img class="book-cover" src="<?= e(bookImage($book['image'])) ?>" alt="<?= e($book['title']) ?>"><div class="book-info"><p class="book-category"><?= e($book['category_name'] ?? 'بدون تصنيف') ?></p><h3><?= e($book['title']) ?></h3><p class="book-author">بقلم <?= e($book['author']) ?></p><?php if ($book['description']): ?><p class="book-author"><?= e(mb_strimwidth($book['description'], 0, 90, '...')) ?></p><?php endif; ?><a class="form-link" href="book.php?id=<?= e($book['id']) ?>">عرض الكتاب ←</a></div></article><?php endforeach; ?></div><?php if ($totalPages > 1): ?><nav class="pagination" aria-label="صفحات الكتب"><?php for ($page = 1; $page <= $totalPages; $page++): ?><a class="<?= $page === $currentPage ? 'active' : '' ?>" href="books.php?search=<?= urlencode($search) ?>&category=<?= e($categoryId) ?>&page=<?= $page ?>"><?= $page ?></a><?php endfor; ?></nav><?php endif; ?><?php endif; ?></div></section>
<?php require __DIR__ . '/includes/footer.php'; ?>